using System;using System.IO;using System.Diagnostics;using System.Linq;using System.Threading;using System.Windows.Forms;
internal static partial class AutoBackground {
 static string MonitorHealth{get{return Path.Combine(Engine.Store,"process-monitor.txt");}}
 static DateTime monitorAttempt;
 internal static string WeixinIdentity(){int session=Process.GetCurrentProcess().SessionId;var list=new System.Collections.Generic.List<string>();foreach(var p in Process.GetProcessesByName("Weixin"))using(p)try{if(p.SessionId==session)list.Add(p.Id+":"+p.StartTime.ToUniversalTime().Ticks);}catch{}list.Sort(StringComparer.Ordinal);return String.Join(",",list);}
 internal static bool MonitorAlive(){try{var v=File.ReadAllLines(MonitorHealth);if(v.Length<4||DateTime.UtcNow.Ticks-long.Parse(v[2])>TimeSpan.FromSeconds(10).Ticks)return false;using(var p=Process.GetProcessById(int.Parse(v[0])))return !p.HasExited&&p.StartTime.ToUniversalTime().Ticks==long.Parse(v[1])&&String.Equals(v[3],Application.ExecutablePath,StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 static void EnsureMonitor(){if(MonitorAlive()||DateTime.UtcNow-monitorAttempt<TimeSpan.FromSeconds(15))return;monitorAttempt=DateTime.UtcNow;Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--monitor"){UseShellExecute=false,CreateNoWindow=true});}
 static void EnsureThemeWorker(){if(!Enabled||SessionExitRequested||WeixinIdentity()==""||ServiceAlive(true)||DateTime.UtcNow-launchAttempt<TimeSpan.FromSeconds(35))return;launchAttempt=DateTime.UtcNow;AppLog.Event("SERVICE","Weixin detected; starting theme worker");Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--watch"){UseShellExecute=false,CreateNoWindow=true});}
 internal static bool NewWeixinStarted(string before,string after){return after.Split(new[]{','},StringSplitOptions.RemoveEmptyEntries).Except(before.Split(new[]{','},StringSplitOptions.RemoveEmptyEntries),StringComparer.Ordinal).Any();}
 internal static void RunMonitor(){using(var gate=new Mutex(false,"Local\\WeixinThemeStudioProcessMonitor")){bool held=false;try{try{held=gate.WaitOne(15000);}catch(AbandonedMutexException){held=true;}if(!held)return;string previous=WeixinIdentity();AppLog.Event("MONITOR","Lightweight detection started; no theme rendering while Weixin is absent");while(Enabled&&String.Equals(ActiveWorkerPath,Application.ExecutablePath,StringComparison.OrdinalIgnoreCase)){string current=WeixinIdentity();if(NewWeixinStarted(previous,current)){ResumeSession();AppLog.Event("MONITOR","New Weixin process identity; resuming theme worker");}previous=current;if(current!="")EnsureThemeWorker();using(var p=Process.GetCurrentProcess())File.WriteAllLines(MonitorHealth,new[]{p.Id.ToString(),p.StartTime.ToUniversalTime().Ticks.ToString(),DateTime.UtcNow.Ticks.ToString(),Application.ExecutablePath,current==""?"等待微信启动（主题后台未加载）":"已检测到微信"});Thread.Sleep(1000);}}catch(Exception e){AppLog.Error("MONITOR",e);}finally{if(held)gate.ReleaseMutex();}}}
}
